package main

import (
	"sort"
	"strings"

	"github.com/Git-on-my-level/agentctl/internal/output"
)

type commandHelp struct {
	Name            string                 `json:"name"`
	Summary         string                 `json:"summary"`
	Usage           string                 `json:"usage"`
	SideEffectClass output.SideEffectClass `json:"side_effect_class"`
	Defaults        []string               `json:"defaults"`
	Examples        [][]string             `json:"examples"`
	Related         []string               `json:"related_topics"`
}

func helpTopics() map[string]commandHelp {
	return map[string]commandHelp{
		"doctor": {
			Name: "doctor", Summary: "Answer whether detected agents can launch, be observed, and return results.", Usage: "agentctl doctor [--adapter name] [--static] [--full]",
			SideEffectClass: output.ReadOnly, Defaults: []string{"checks bootstrap, journal, configuration, supervisor, and detected adapters", "live capability probes are enabled"},
			Examples: [][]string{{"agentctl", "doctor"}, {"agentctl", "doctor", "--adapter", "cursor"}}, Related: []string{"bootstrap", "capabilities", "run"},
		},
		"bootstrap": {
			Name: "bootstrap", Summary: "Inspect or reconcile agentctl across detected local harnesses.", Usage: "agentctl bootstrap status|update|adopt [flags]",
			SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"status is read-only and reports instruction pointer path, state, digest, and revision per harness", "update detects supported harnesses and canonical roots", "update heals, appends, or creates documented user-global instruction pointers unless config sets bootstrap.instruction_pointers=off", "update refuses drifted user-edited pointer bodies and duplicate unmanaged skill collisions"},
			Examples: [][]string{{"agentctl", "bootstrap", "status"}, {"agentctl", "bootstrap", "update", "--dry-run"}, {"agentctl", "bootstrap", "update"}}, Related: []string{"bootstrap update", "doctor"},
		},
		"bootstrap adopt": {
			Name: "bootstrap adopt", Summary: "Plan explicit adoption of an exact published legacy skill.", Usage: "agentctl bootstrap adopt --harness name [--home path] [--target-dir path] [--apply --expected-digest sha256:...]",
			SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"read-only plan unless --apply", "one exact local harness root", "only bundled published hashes", "apply requires the complete plan digest and keeps a backup", "custom files, symlinks, and modified content are conflicts", "does not edit instruction pointers or Multica workspace state"},
			Examples: [][]string{{"agentctl", "bootstrap", "adopt", "--harness", "hermes"}}, Related: []string{"bootstrap update", "bootstrap"},
		},
		"bootstrap update": {
			Name: "bootstrap update", Summary: "Reconcile the embedded portable skill and delegation pointers for detected harnesses.", Usage: "agentctl bootstrap update [--dry-run] [--no-instruction-pointers] [--harness names] [--home path] [--target-dir path]",
			SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"all detected harnesses", "canonical skill roots", "managed skill upgrades, missing installs, and digest-matching unmarked copies", "instruction pointers append to existing unmarked files, create missing documented files except OMP, repair a truncated marker, and upgrade exact shipped revisions", "duplicate and user-edited pointer blocks remain conflicts", "opt out with bootstrap.instruction_pointers=off or --no-instruction-pointers", "no legacy-copy deletion", "no new supervisor service"},
			Examples: [][]string{{"agentctl", "bootstrap", "update", "--dry-run"}, {"agentctl", "bootstrap", "update"}, {"agentctl", "bootstrap", "update", "--harness", "cursor"}, {"agentctl", "bootstrap", "update", "--no-instruction-pointers"}}, Related: []string{"bootstrap", "doctor"},
		},
		"capabilities": {
			Name: "capabilities", Summary: "Return a concise live viability projection for one adapter.", Usage: "agentctl capabilities <adapter> [--require names] [--full] [--static] [--executable path]",
			SideEffectClass: output.ReadOnly, Defaults: []string{"concise summary", "live probe", "all capabilities when --require is omitted"},
			Examples: [][]string{{"agentctl", "capabilities", "codex"}, {"agentctl", "capabilities", "cursor", "--require", "launch,result_content"}}, Related: []string{"doctor", "run"},
		},
		"orient": {
			Name: "orient", Summary: "Describe the current worktree, configured authorities, static adapter health, and workspace-scoped executions in one read-only snapshot.", Usage: "agentctl orient [--limit n]",
			SideEffectClass: output.ReadOnly, Defaults: []string{"current working directory", "at most 10 workspace-matched execution records total", "newest active executions first, then newest terminal executions within the remaining limit", "no Git fetch", "no adapter launch or remote authentication probe", "journal opens read-only and an absent journal is reported as unconfigured", "raw prompts, transcripts, results, and per-execution paths omitted", "static adapter health proves only local executable availability"},
			Examples: [][]string{{"agentctl", "orient"}, {"agentctl", "orient", "--limit", "25"}}, Related: []string{"doctor", "recent", "route"},
		},
		"delegate": {
			Name: "delegate", Summary: "Default way to start a native agent: resolve a selector and apply reviewed permission defaults.",
			Usage:           "agentctl delegate --request-file path (--prompt-file path|--prompt-stdin) [--cwd path] [--plan] [--wait [--content] [--require-result-source source] [--min-result-bytes n]] [--timeout duration] [--label name ...] [--authority auto|native|multica]",
			SideEffectClass: output.ExternalSideEffect,
			Defaults:        []string{"preferred over expert run for kicking off a new agent", "send review feedback or the next instruction to a finished delegated agent with agentctl continue; it resumes the same native session", "a running delegated agent can be redirected with agentctl steer when its plan reports a steer route", `request example: {"schema_version":1,"request_key":"review-01","selector":{"family":"grok"}}`, "parent extracts only explicit constraints; omitted values use compatible reviewed defaults", "omitted settings.access means coding", "coding launches add Cursor --force and Codex --dangerously-bypass-approvals-and-sandbox only when delegation.unattended_coding_permissions is true", "settings.access read_only uses Cursor --mode ask and Codex --sandbox read-only and never adds those bypass flags", "Cursor --trust still requires the separate delegation.cursor_workspace_trust grant", "harnesses without a reviewed bypass flag are labeled permissions=unsupported and are not given an inferred flag", "preferred entries are the allowlist; configure family/version metadata; omitted host means local", "conflicting or ambiguous selectors launch nothing; no fuzzy matching or fallback", "invalid requests report sanitized field paths, allowed keys and placeholder examples; selection errors return bounded reviewed catalog candidates", "request files are regular non-symlinks, strict JSON, at most 64 KiB", "prompt is separate and never journaled; prompt files must be within cwd and at most 8 MiB", "plans may probe versions but never write state or run maintenance; inspect native.argv, native.env, and native.permissions before launching", "same profile, request key, and inputs recover original work despite changed defaults; changed inputs conflict", "foreground ownership; no background or external context handles", "wait requires successful completion and nonempty content before collection acknowledgement", "without wait a receipt does not assert successful work", "no default execution timeout", "ZCode GLM-5.3-Flash sets ZCODE_MODEL and needs a provisioned per-model config; GLM-5.3 keeps its configured default", "native settings describe requested identity, not provider attestation", "remote and Multica delegation fail before launch until result and settings guarantees exist"},
			Examples:        [][]string{{"agentctl", "delegate", "--request-file", "request.json", "--prompt-file", "task.md", "--plan"}, {"agentctl", "delegate", "--request-file", "request.json", "--prompt-file", "task.md", "--wait"}},
			Related:         []string{"schema", "config", "run", "dispatch", "result", "recent", "continue", "steer"},
		},
		"identity": {
			Name: "identity", Summary: "Read provider, native-conversation correlation, and capability evidence without probes or writes.", Usage: identityUsage,
			SideEffectClass: output.ReadOnly,
			Defaults:        []string{"JSON result schema agentctl.identity.v1", "unknown identity is null; environment and explicit hints are self-reported", "managed execution evidence suppresses inherited native conversation environment", "native session IDs are provider-scoped hashes, never resume handles or agent principals", "consumers add their independently enrolled host namespace", "executable presence is inventory, not active identity or capability", "expert run does not gain continuation without a frozen delegation recipe"},
			Examples:        [][]string{{"agentctl", "identity", "--json"}, {"agentctl", "identity", "--provider", "custom-agent", "--native-session-id", "example-session"}}, Related: []string{"doctor", "capabilities", "continue", "schema"},
		},

		"run": {
			Name: "run", Summary: "Expert path: launch an exact native argv and persist its normalized execution and terminal result. Does not apply delegate permission defaults.", Usage: "agentctl run [--execution-id exec-...] [--label name ...] [--task-contract json-file] [--adapter name] [--timeout duration|--no-timeout] [--prompt-file path|--prompt-stdin] [--prompt-delivery argv|stdin|stream] [flags] -- <native argv>",
			SideEffectClass: output.ExternalSideEffect, Defaults: []string{"prompt-root errors provide a structured stdin-source repair without changing native delivery", "plans expose foreground ownership, cancellation limits, and result collection semantics", "adapter inferred from known executable names", "execution ID generated unless preallocated", "foreground ownership; --background is rejected", "parent-background a foreground run, or use dispatch for work that must outlive this process", "up to 16 exact metadata labels", "task contracts are bounded strict JSON metadata retained by status and result", "native completion never implies external acceptance", "Multica issues remain authoritative for Multica task contracts", "no wall-clock timeout", "prompt delivery argv when a prompt source is selected", "prompt delivery stream holds native stdin open for live steering and requires the adapter's live input argv", "steering needs an agentctl-managed prompt source; a prompt embedded in native argv cannot be steered", "prompt files are regular non-symlinks within --cwd and at most 8 MiB", "invocation-scoped launch and result_content preflight", "bounded final result storage", "Cursor plan mode rejected because its one-shot completion is unreliable", "off-policy argv against agent_preferences warns and still launches"},
			Examples: [][]string{{"agentctl", "run", "--", "codex", "exec", "--json", "review this change"}, {"agentctl", "run", "--task-contract", "task-contract.json", "--", "codex", "exec", "--json", "perform the bounded task"}, {"agentctl", "run", "--label", "review", "--prompt-file", "task.md", "--prompt-delivery", "argv", "--", "cursor-agent", "--print", "--output-format", "stream-json", "--trust"}, {"agentctl", "run", "--prompt-stdin", "--prompt-delivery", "stdin", "--", "codex", "exec", "--json", "-"}}, Related: []string{"recent", "fanout", "capabilities", "await", "result", "dispatch"},
		},
		"dispatch": {
			Name: "dispatch", Summary: "Create or recover routed Multica work and persist a tracked execution handle.", Usage: "agentctl dispatch --route selector --title title (--prompt-file path|--prompt-stdin) --idempotency-key key [--project ID] [--status status] [--label name ...] [--plan]",
			SideEffectClass: output.RemoteCoordinationWrite, Defaults: []string{"status retains bounded last_operation_failure; retry the original key and inputs after resolving its category", "live agent and runtime resolution from the configured Multica workspace", "exact routed host, adapter, and concrete model required", "off-policy adapter+model against agent_preferences fails closed", "unarchived idle or working agent and online runtime required", "exact assignee and runtime reserved in a local starting execution before the remote call", "replay recovers the prepared target without mutable fleet resolution", "assigned backlog creation is bound locally before todo activation unless --status is explicit", "status must be one of Multica's seven lifecycle statuses", "caller idempotency key required", "prompt delivered only on Multica stdin and never journaled", "returns a Multica-authority exec ID", "no local fallback", "--plan performs live read-only resolution without creating an issue or journal record"},
			Examples: [][]string{{"agentctl", "dispatch", "--route", "m5 sol", "--title", "Review the release", "--prompt-file", "task.md", "--idempotency-key", "release-review-v1", "--plan"}, {"agentctl", "dispatch", "--route", "m5 sol", "--title", "Review the release", "--prompt-stdin", "--idempotency-key", "release-review-v1"}}, Related: []string{"route", "await", "subscribe", "recent", "promote"},
		},
		"recent":           {Name: "recent", Summary: "Discover recent host-local executions without reading prompt or result records.", Usage: "agentctl recent [--limit n] [--state state|terminal|nonterminal] [--liveness value] [--unreconciled] [--adapter name] [--label name ...] [--caller harness|unknown] [--since RFC3339] [--until RFC3339] [--cursor token|--summary]", SideEffectClass: output.ReadOnly, Defaults: []string{"newest 20 executions", "--since includes the creation timestamp; --until excludes it", "--cursor preserves creation cutoff and binds journal/filter scope; repeat the original filters", "states and acknowledgements are live per page, not a persisted snapshot", "--summary aggregates the entire filtered retained set without reading results or acknowledging", "caller attribution is explicitly declared; absent means unknown", "preflight failures are not recorded in this export", "total reports the full filtered set while count reports the returned projection", "host-local journal only", "state and liveness are independent exact filters", "repeated exact label filters use AND semantics", "--unreconciled is terminal work whose result has never been acknowledged", "terminals that predate acknowledgement tracking are not unreconciled", "acknowledgement_source distinguishes result, await, and bulk_reconciled", "paths, prompts, transcripts, and results omitted"}, Examples: [][]string{{"agentctl", "recent"}, {"agentctl", "recent", "--state", "nonterminal", "--liveness", "alive", "--label", "review"}, {"agentctl", "recent", "--liveness", "unreachable"}, {"agentctl", "recent", "--unreconciled"}}, Related: []string{"status", "await", "result"}},
		"inbox":            {Name: "inbox", Summary: "Explain host-local executions that need collection, intervention, integrity reconciliation, or bounded stale-work review.", Usage: "agentctl inbox [--limit n] [--stale-after duration] [--adapter name] [--label name ...]", SideEffectClass: output.ReadOnly, Defaults: []string{"newest 20 actionable executions", "total reports the full actionable set while count reports the returned projection", "one hour stale-observation bound", "host-local journal only", "terminal failures leave the inbox when result or terminal await acknowledges collection", "conflicted evidence remains actionable after collection", "work health and tool liveness are reported separately", "stale recovery guidance uses recorded capability and exact authority bindings; no inferred success or cross-process control", "no adapter probe, native status refresh, result read, or acknowledgement write", "execution paths, prompts, transcripts, and results omitted; action argv preserves explicitly supplied configuration and journal paths"}, Examples: [][]string{{"agentctl", "inbox"}, {"agentctl", "inbox", "--stale-after", "2h", "--label", "review"}}, Related: []string{"recent", "status", "await", "result", "reconcile"}},
		"reconcile":        {Name: "reconcile", Summary: "Plan or apply host-local repair for provably lost native owners and old uncollected terminals.", Usage: "agentctl reconcile [--stale-after duration] [--collect-older-than duration] [--legacy-stale-after duration] [--adapter name] [--label name ...] [--include-failures] [--include-legacy-unproven] (--plan|--apply --plan-digest sha256:...)", SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"exactly one of --plan or --apply", "--plan writes nothing", "--apply requires --plan-digest from the reviewed plan and writes nothing when the recomputed candidate ids, actions, and proofs differ", "stale-after defaults to 24h and accepts 1m through 720h", "collect-older-than defaults to 168h (7d) and accepts 1m through 8760h", "a trailing d means exact 24-hour days", "native nonterminal executions become orphaned only when the launcher-recorded PID is provably gone and the last observation is older than stale-after", "orphaned means owner lost and outcome unknown; it is not failed or succeeded", "a numeric session id is not a PID; rows without the launcher record are ownership_unproven unless --include-legacy-unproven", "--include-legacy-unproven is off by default", "legacy-stale-after defaults to 168h and accepts 72h through 8760h", "a legacy row must be native, match the journal host id, have no launch record, and have a last observation older than legacy-stale-after", "legacy rows are listed under legacy_orphan, included in plan_digest, and recorded with evidence heartbeat_absent", "heartbeat_absent is a multi-day gap from the runner's 10s heartbeat; it is evidence, not proof the process is gone", "the legacy outcome is orphaned with owner_unproven_legacy and is never owner_lost", "a legacy numeric PID that currently exists is left unchanged and reported legacy_pid_present, without comparing start time; one whose absence cannot be proved is left unchanged and reported legacy_pid_unproven", "an unexpired runner lease is left unchanged", "a live PID, an unexpired runner lease, a recent observation, or unproven start identity is left unchanged", "Linux absence is proved only when the recorded pid namespace matches and /proc/1 or the proving process's parent is visible; missing launch start ticks are unproven, not pid reuse", "completed and cancelled terminals older than collect-older-than are stamped bulk_reconciled without reading result content", "bulk_reconciled is shown by recent and status and makes that result eligible for data cleanup", "failed, orphaned, and integrity-conflicted terminals stay uncollected unless --include-failures", "terminals that predate acknowledgement tracking are already reconciled", "journal_host_match compares origin_host_id with the host id stored in this journal and is not a machine fingerprint", "Multica issue state is not changed; local collection stamps are written", "nonterminal Multica executions older than stale-after are reported with their issue binding; reconcile does not call Multica", "repeated --label filters use AND semantics"}, Examples: [][]string{{"agentctl", "reconcile", "--plan"}, {"agentctl", "reconcile", "--stale-after", "24h", "--collect-older-than", "7d", "--adapter", "cursor", "--plan"}, {"agentctl", "reconcile", "--apply", "--plan-digest", "sha256:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"}}, Related: []string{"inbox", "result", "recent"}},
		"workspace":        {Name: "workspace", Summary: "Group the Git-worktree scoped views of host-local executions.", Usage: "agentctl workspace owners [--path directory]", SideEffectClass: output.ReadOnly, Defaults: []string{"owners is the only subcommand; the bare group name is not a command"}, Examples: [][]string{{"agentctl", "workspace", "owners"}}, Related: []string{"workspace owners", "recent", "status"}},
		"workspace owners": {Name: "workspace owners", Summary: "Report nonterminal executions launched from Git worktrees.", Usage: "agentctl workspace owners [--path directory]", SideEffectClass: output.ReadOnly, Defaults: []string{"host-local journal only", "all attributed nonterminal executions when --path is omitted", "exact Git worktree match when --path is supplied", "launch-time provenance, never an exclusive lock", "older nonterminal rows without workspace metadata make evidence_complete false"}, Examples: [][]string{{"agentctl", "workspace", "owners"}, {"agentctl", "workspace", "owners", "--path", "/absolute/worktree"}}, Related: []string{"recent", "status", "schema"}},
		"fanout": {
			Name: "fanout", Summary: "Delegate shared or distinct tasks through explicit native argv vectors with bounded concurrency.", Usage: "agentctl fanout --manifest path [--concurrency n] [--fail-fast] [--plan]",
			SideEffectClass: output.ExternalSideEffect, Defaults: []string{"manifest v1 requires schema_version, children[].argv, and a shared or per-child prompt_file", "prompt files and relative children[].cwd resolve from the manifest directory", "a child without cwd inherits the invoking process directory", "prompt_delivery is argv or stdin globally or per child", "optional unique child names correlate results; shared and child labels are a stable union of at most 16 labels", "all children preflight before any task launch; native read-only version probes may execute", "preflight is not an atomic launch reservation", "foreground same-process coordination", "concurrency 2; callbacks admitted in manifest order", "each unique prompt file read once; 64 MiB total prompt bound", "existing execution IDs fail preflight; no replay or automatic retry", "fail-fast cancels admitted siblings and skips queued children", "per-child launch_attempted, recorded, state, error, and prompt digest; no raw prompts", "no automatic synthesis, group authority, or detached ownership"},
			Examples: [][]string{{"agentctl", "schema", "list"}, {"agentctl", "fanout", "--plan", "--manifest", "fanout.json"}, {"agentctl", "fanout", "--manifest", "fanout.json"}}, Related: []string{"schema", "run", "await", "result"},
		},
		"await": {
			Name: "await", Summary: "Wait for terminal state or attention without polling native session files.", Usage: "agentctl await <execution-id> [--timeout duration|--no-timeout|--through-execution-deadline] [--ignore-attention]",
			SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"no timeout", "returns immediately when attention is required", "Multica-authority executions are refreshed from the bound issue status while awaiting", "two consecutive retryable Multica refresh failures are tolerated; the third returns its diagnostic", "a terminal return acknowledges the execution so it is no longer unreconciled"},
			Examples: [][]string{{"agentctl", "await", "exec-..."}, {"agentctl", "await", "exec-...", "--through-execution-deadline"}, {"agentctl", "await", "exec-...", "--no-timeout", "--ignore-attention"}}, Related: []string{"status", "events", "result"},
		},
		"result": {
			Name: "result", Summary: "Dereference and optionally assert guarantees on a bounded terminal result, one execution or the whole uncollected set.", Usage: "agentctl result <execution-id> [--content|--summary] [--allow-empty] [--require-result-source source] [--min-result-bytes n] | agentctl result --unreconciled [--label name ...] [--limit n] [--before execution-id] [--summary] [--allow-empty]",
			SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"pending results provide an await next action; inspect recorded dispatch failures before waiting", "stored content or a structured failure is required", "--content writes exact stored UTF-8 text with no envelope and no added newline", "integrity conflicts fail closed", "a successful dereference acknowledges the execution so it is no longer unreconciled", "--unreconciled collects the newest 50 uncollected terminal results through the same single-execution contract", "--unreconciled reports total alongside count for the filtered set before the exclusive cursor", "--before takes a full execution ID in this journal; continuation preserves scope, labels, summary, and allow-empty and advances past skipped items; retry without the cursor to revisit skips", "an execution that cannot be dereferenced is reported and skipped instead of failing the batch", "acknowledgement stamps are first-write-wins, so re-running collects only what remains", "--unreconciled rejects --content, --require-result-source, and --min-result-bytes because each describes exactly one result"},
			Examples: [][]string{{"agentctl", "result", "exec-..."}, {"agentctl", "result", "exec-...", "--content"}, {"agentctl", "result", "exec-...", "--require-result-source", "assistant", "--min-result-bytes", "200"}, {"agentctl", "result", "--unreconciled"}, {"agentctl", "result", "--unreconciled", "--label", "review", "--limit", "100", "--summary"}}, Related: []string{"run", "await", "events", "recent", "inbox"},
		},
		"subscribe": {
			Name: "subscribe", Summary: "Create durable at-least-once callback delivery for execution events.", Usage: "agentctl subscribe create --execution ID --destination file|webhook --target target [--authority direct|multica] [--kind kind] [--ttl duration] [--keep-after-terminal] | list | show ID | cancel ID",
			SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"create filters terminal, attention, and artifact events", "24 hour TTL", "expires after acknowledged terminal delivery", "acknowledged events stay in the journal and are delivered only when --kind lists acknowledged; --kind all does not include them"},
			Examples: [][]string{{"agentctl", "subscribe", "create", "--execution", "exec-...", "--destination", "file", "--target", "/absolute/events.ndjson"}}, Related: []string{"run", "events", "supervisor"},
		},
		"status":        {Name: "status", Summary: "Read one normalized execution envelope.", Usage: "agentctl status <execution-id>", SideEffectClass: output.ReadOnly, Defaults: []string{"native paths, prompts, and transcripts remain redacted", "acknowledgement_source distinguishes result, await, and bulk_reconciled when a collection stamp exists"}, Examples: [][]string{{"agentctl", "status", "exec-..."}}, Related: []string{"events", "await", "result"}},
		"events":        {Name: "events", Summary: "Read bounded normalized event history.", Usage: "agentctl events <execution-id> [--after-sequence n] [--limit n] [--kind kind]", SideEffectClass: output.ReadOnly, Defaults: []string{"after sequence 0", "limit 100", "all semantic event kinds"}, Examples: [][]string{{"agentctl", "events", "exec-..."}, {"agentctl", "events", "exec-...", "--kind", "terminal"}}, Related: []string{"status", "subscribe", "await"}},
		"promote":       {Name: "promote", Summary: "Explicitly create or recover a Multica issue for a direct execution.", Usage: "agentctl promote <execution-id> --title title [--handoff-file path] [--plan]", SideEffectClass: output.RemoteCoordinationWrite, Defaults: []string{"performs the remote mutation", "idempotent for identical semantics"}, Examples: [][]string{{"agentctl", "promote", "exec-...", "--title", "Durable follow-up", "--plan"}}, Related: []string{"route", "config"}},
		"route":         {Name: "route", Summary: "Explain ranked host/model matches from a short selector; never launch or dispatch work.", Usage: "agentctl route explain <selector...>", SideEffectClass: output.ReadOnly, Defaults: []string{"a non-empty short selector ranks reviewed host/model aliases", "when agent_preferences exist, only those reviewed models match", "task prose and lifecycle intent are not inferred", "remote advice does not verify a Multica assignee/runtime or create an exec id", "this_host must be configured before local versus remote placement is claimed"}, Examples: [][]string{{"agentctl", "route", "explain", "--", "studio", "omp"}}, Related: []string{"run", "dispatch", "promote"}},
		"supervisor":    {Name: "supervisor", Summary: "Run, inspect, or plan the host-local callback supervisor.", Usage: "agentctl supervisor run|status|plan ...", SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"Unix socket only", "status includes startup PID, version, and executable digest", "one service process per state directory; socket cleanup is identity-bound", "status requests time out after five seconds", "reprobes release journal locks during adapter I/O and back off failed revisions", "new service installation remains explicit"}, Examples: [][]string{{"agentctl", "supervisor", "status"}}, Related: []string{"subscribe", "bootstrap"}},
		"update":        {Name: "update", Summary: "Inspect or control invocation-triggered agentctl release updates.", Usage: "agentctl update status|now|policy auto|notify|off", SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"status separates observed binary from installer records and exposes allowlisted failure stage, exit code, and rollback outcome", "auto policy", "first work-creating invocation per UTC day starts a detached short-lived worker", "read-only commands never trigger automatic maintenance", "managed packaged installations only", "status is read-only", "now forces a fresh release check, reconciles installed version state, and is a no-op when current", "a rate-limited release API falls back to the public same-origin latest-release redirect", "notify emits one daily update warning on eligible invocations", "off performs no release check"}, Examples: [][]string{{"agentctl", "update", "status"}, {"agentctl", "update", "policy", "notify"}, {"agentctl", "update", "now"}}, Related: []string{"bootstrap", "doctor"}},
		"config":        {Name: "config", Summary: "Manage executable provenance expectations, advisory agent preferences, optional authority, and explicit local or Git-backed configuration.", Usage: "agentctl config set-profile|show|validate|doctor|bundle|source ...", SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"agent preferences are advisory", "no implicit unauthenticated Multica profile", "Git sources are explicit and fast-forward only", "native run argv remains caller-authoritative"}, Examples: [][]string{{"agentctl", "config", "show"}, {"agentctl", "config", "source", "status"}, {"agentctl", "--config-bundle", "/local/config-bundle.json", "config", "bundle", "plan"}}, Related: []string{"config source", "doctor", "promote"}},
		"config source": {Name: "config source", Summary: "Materialize a reviewed Git config bundle into the owner-only live config.", Usage: "agentctl config source init --remote URL [--ref main] [--bundle config-bundle.json] [--checkout path] [--plan] | status | update [--plan] | restore [--plan]", SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"status and --plan perform no fetch", "first init may add missing fields but never replace existing values", "update fetches noninteractively and accepts fast-forwards only", "restore repairs only the live config from the pinned clean checkout", "dirty checkouts and unreviewed history fail closed", "Git and SSH own credentials"}, Examples: [][]string{{"agentctl", "config", "source", "init", "--remote", "git@github.com:owner/agentctl-config.git", "--plan"}, {"agentctl", "config", "source", "update"}, {"agentctl", "config", "source", "status"}}, Related: []string{"config", "doctor"}},
		"skills":        {Name: "skills", Summary: "Fetch a config-selected Skill Hub pack, reconcile clean managed copies, and preserve local drift for review.", Usage: "agentctl skills plan|status|doctor|update|reconcile|diff|restore|propose ...", SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"plan, status, doctor, update --plan, diff, restore plan, and propose plan are read-only", "Skill Hub updates are fast-forward only", "auto-clean replaces only unchanged marker-owned copies", "drift and unmanaged collisions are preserved", "agentctl-portable is bootstrap-owned and reserved", "publishing a proposal is always separate"}, Examples: [][]string{{"agentctl", "skills", "update", "--plan"}, {"agentctl", "skills", "update"}, {"agentctl", "skills", "diff", "example-skill"}, {"agentctl", "skills", "propose", "example-skill"}}, Related: []string{"config source", "bootstrap update", "update", "doctor"}},
		"data":          {Name: "data", Summary: "Inventory local journal data and explicitly plan retention cleanup.", Usage: "agentctl data inventory | agentctl data cleanup --before timestamp [--include-unreconciled] --plan | --apply --plan-digest digest", SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"inventory and cleanup planning are read-only", "no automatic retention", "cleanup apply requires the reviewed plan digest", "terminal results nobody collected are protected from cleanup"}, Examples: [][]string{{"agentctl", "data", "inventory"}, {"agentctl", "data", "cleanup", "--before", "2026-07-01T00:00:00Z", "--plan"}}, Related: []string{"data cleanup", "result"}},
		"data cleanup":  {Name: "data cleanup", Summary: "Plan or atomically remove unreferenced terminal execution graphs before a cutoff.", Usage: "agentctl data cleanup --before RFC3339 [--include-unreconciled] --plan | agentctl data cleanup --before RFC3339 [--include-unreconciled] --apply --plan-digest sha256:...", SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"no deletion without --apply and a matching reviewed plan digest", "nonterminal and referenced graphs are protected", "terminal executions whose result was never collected are protected with reason result_unreconciled", "terminals that predate acknowledgement tracking on that journal stay eligible", "--include-unreconciled is the explicit opt-out and changes the plan digest", "protected_unreconciled counts the results retained only because nobody collected them", "a bulk_reconciled stamp is collection for this purpose and makes the execution eligible for deletion", "physical journal compaction is not automatic"}, Examples: [][]string{{"agentctl", "data", "cleanup", "--before", "2026-07-01T00:00:00Z", "--plan"}, {"agentctl", "data", "cleanup", "--before", "2026-07-01T00:00:00Z", "--apply", "--plan-digest", "sha256:..."}, {"agentctl", "data", "cleanup", "--before", "2026-07-01T00:00:00Z", "--include-unreconciled", "--plan"}}, Related: []string{"data", "result"}},
		"knowledge":     {Name: "knowledge", Summary: "Validate, synchronize, compile, or verify deterministic knowledge bundles.", Usage: "agentctl knowledge validate|sync|compile|verify ...", SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"validation and sync planning do not fetch Git", "credentials and harness state are forbidden"}, Examples: [][]string{{"agentctl", "knowledge", "validate", "--source", "source.json"}}, Related: []string{"context"}},
		"context":       {Name: "context", Summary: "Select deterministic task context from a verified bundle.", Usage: "agentctl context --bundle path --repository path --task-kind kind --query query [--render path]", SideEffectClass: output.LocalOperationalWrite, Defaults: []string{"read-only unless --render is supplied"}, Examples: [][]string{{"agentctl", "context", "--bundle", "/bundle", "--query", "deployment"}}, Related: []string{"knowledge"}},
		"attach":        {Name: "attach", Summary: "Resolve a portable URI through reviewed local bindings.", Usage: "agentctl attach <portable-uri>", SideEffectClass: output.ReadOnly, Defaults: []string{"foreign hosts fail closed", "authority state is never guessed"}, Related: []string{"status"}},
		"cancel":        {Name: "cancel", Summary: "Request cancellation for native execs or thin-forward Multica-authority execs to issue cancel-task.", Usage: "agentctl cancel <execution-id>", SideEffectClass: output.ExternalSideEffect, Defaults: []string{"native/direct execs use the adapter cancel path and terminalize locally", "Multica-authority execs forward to issue cancel-task using bound issue+task", "Multica success means the cancel request was accepted, not that the remote run has already stopped", "never guesses from a PID"}, Related: []string{"status", "capabilities", "await"}},
		"continue": {Name: "continue", Summary: "Send a follow-up turn to the native session of a completed delegated execution.", Usage: "agentctl continue <execution-id> --request-key key (--prompt-file path|--prompt-stdin) [--plan] [--wait [--content] [--require-result-source source] [--min-result-bytes n]] [--timeout duration] [--label name ...]", SideEffectClass: output.ExternalSideEffect,
			Defaults: []string{"the follow-up is a new execution with its own result; it supersedes the execution it continues",
				"the native CLI resumes its own session, so the agent keeps the conversation and agentctl stores no transcript",
				"launches the frozen recipe of the original delegate (same harness, model, settings, and permissions) in the original working directory",
				"only a completed delegated execution can be continued; expert run records no recipe, and a failed or cancelled turn may not have kept its context",
				"continue from the latest completed turn; an older turn reports the latest execution to use",
				"one follow-up runs at a time per session; a concurrent attempt is refused without launching and does not use up its request key",
				"result shape: schemas/continue-result.schema.json",
				"--request-key makes a retry of the same prompt recover the same turn instead of sending it twice",
				"labels default to the continued execution's labels",
				"harnesses with no verified resume route, or that report no session id, are refused with the reason",
				"use steer, not continue, to redirect an execution that is still running",
				"--plan is read-only and shows the native argv with the session id redacted"},
			Examples: [][]string{{"agentctl", "continue", "exec-...", "--request-key", "review-01-round-2", "--prompt-file", "feedback.md", "--plan"}, {"agentctl", "continue", "exec-...", "--request-key", "review-01-round-2", "--prompt-file", "feedback.md", "--wait", "--content"}},
			Related:  []string{"delegate", "steer", "result", "await"}},
		"steer": {Name: "steer", Summary: "Send a new instruction to a running native execution through the agentctl process that owns it.", Usage: "agentctl steer <execution-id> (--prompt-file path|--prompt-stdin) [--allow-interrupt] [--idempotency-key key] [--timeout duration] [--plan]", SideEffectClass: output.ExternalSideEffect,
			Defaults: []string{"the route is fixed when the execution launches and is reported by --plan and by status capabilities",
				"live_input: the message is written to the native input stream and the agent takes it at its next turn boundary; the execution's final answer is the answer to the last message",
				"interrupt_resume: the native process is stopped and the same native session is resumed with the message; the in-flight turn is discarded, so --allow-interrupt is required",
				"interrupt_resume waits for the native session id; a failed resume fails the execution",
				"interrupt_resume can lose what the agent learned inside the interrupted turn (Codex keeps only the conversation up to the launch prompt); restate anything it must keep in the message",
				"status delivered means the native session itself took the message: it acknowledged it (live_input) or was resumed with it (interrupt_resume); it is not proof the agent acted on it",
				"status queued (live_input only) means the owner accepted the message for the native input stream and the session had not taken it before --timeout; it is not withdrawn, and a later steer_delivered or steer_rejected event settles it",
				"a queued message the session never takes is rejected as steer_unacknowledged when the execution ends",
				"result shape: schemas/steer-result.schema.json",
				"the journal records the message digest and size, never its text",
				"a request the owner did not take before --timeout (default 60s) is withdrawn and reported as not delivered",
				"--idempotency-key with the same message returns the recorded outcome instead of delivering twice; for a queued request it waits for the acknowledgement",
				"terminal, Multica-authority, and route-less executions are rejected without side effects; use continue for a finished execution",
				"--plan is read-only"},
			Examples: [][]string{{"agentctl", "steer", "exec-...", "--prompt-file", "steer.md", "--plan"}, {"agentctl", "steer", "exec-...", "--prompt-file", "steer.md"}, {"agentctl", "steer", "exec-...", "--prompt-file", "steer.md", "--allow-interrupt"}},
			Related:  []string{"status", "capabilities", "await", "delegate", "continue"}},
		"id":     {Name: "id", Summary: "Generate or inspect typed six-word identifiers.", Usage: "agentctl id generate <type> | agentctl id inspect <id>", SideEffectClass: output.ReadOnly, Defaults: []string{"full typed IDs are mutation targets"}, Examples: [][]string{{"agentctl", "id", "generate", "exec"}}},
		"schema": {Name: "schema", Summary: "List normative JSON schema files.", Usage: "agentctl schema list", SideEffectClass: output.ReadOnly, Defaults: []string{}, Examples: [][]string{{"agentctl", "schema", "list"}}},
	}
}

func (a *app) help(renderer output.Renderer, rawTopic string) int {
	topic := strings.ToLower(strings.Join(strings.Fields(rawTopic), " "))
	topics := helpTopics()
	if topic != "" {
		aliases := map[string]string{
			"list":             "recent",
			"bootstrap status": "bootstrap", "route explain": "route",
			"subscribe create": "subscribe", "subscribe list": "subscribe", "subscribe show": "subscribe", "subscribe cancel": "subscribe",
			"supervisor run": "supervisor", "supervisor status": "supervisor", "supervisor plan": "supervisor",
			"update status": "update", "update now": "update", "update policy": "update",
			"config set-profile": "config", "config show": "config", "config validate": "config", "config doctor": "config", "config bundle": "config", "config bundle validate": "config", "config bundle show": "config", "config bundle plan": "config", "config source init": "config source", "config source status": "config source", "config source update": "config source", "config source restore": "config source", "skills plan": "skills", "skills status": "skills", "skills doctor": "skills", "skills update": "skills", "skills reconcile": "skills", "skills diff": "skills", "skills restore": "skills", "skills propose": "skills",
			"data inventory":     "data",
			"knowledge validate": "knowledge", "knowledge sync": "knowledge", "knowledge compile": "knowledge", "knowledge verify": "knowledge",
		}
		if canonical, ok := aliases[topic]; ok {
			topic = canonical
		}
		item, ok := topics[topic]
		if !ok {
			return a.fail(renderer, output.NewError(output.CodeNotFound, "help topic not found", false).WithDetail("topic", topic))
		}
		lines := []output.Line{{Lead: "help", Fields: []output.Field{{Name: "topic", Value: item.Name}, {Name: "summary", Value: item.Summary}}}, {Lead: "usage", Fields: []output.Field{{Name: "argv", Value: item.Usage}}}}
		for _, value := range item.Defaults {
			lines = append(lines, output.Line{Lead: "default", Fields: []output.Field{{Name: "behavior", Value: value}}})
		}
		for _, argv := range item.Examples {
			lines = append(lines, output.Line{Lead: "example", Fields: []output.Field{{Name: "argv", Value: argv}}})
		}
		actions := make([]output.NextAction, 0, len(item.Related))
		for _, related := range item.Related {
			actions = append(actions, output.NextAction{Label: "Discover " + related, Argv: []string{"agentctl", "help", related}, Mutates: false, SideEffectClass: output.ReadOnly, Preconditions: []string{}})
		}
		_ = renderer.Success(output.Success{Result: item, Lines: lines, NextActions: actions})
		return 0
	}

	names := make([]string, 0, len(topics))
	for name := range topics {
		names = append(names, name)
	}
	sort.Strings(names)
	commands := make([]map[string]any, 0, len(names))
	lines := []output.Line{{Lead: "agentctl", Fields: []output.Field{{Name: "version", Value: version}}}, {Lead: "usage", Fields: []output.Field{{Name: "argv", Value: "agentctl help <topic>"}}}}
	for _, name := range names {
		item := topics[name]
		commands = append(commands, map[string]any{"name": item.Name, "summary": item.Summary, "side_effect_class": item.SideEffectClass})
		lines = append(lines, output.Line{Lead: "topic", Fields: []output.Field{{Name: "name", Value: item.Name}, {Name: "summary", Value: item.Summary}}})
	}
	result := map[string]any{"name": "agentctl", "version": version, "commands": commands, "global_flags": []string{"--output json|text (default json)", "--profile <name>", "--context-file <path>", "--explain", "--config <path>", "--config-bundle <explicit-local-path>", "--journal <path>"}, "discovery": []string{"agentctl help <topic>", "agentctl doctor"}}
	_ = renderer.Success(output.Success{Result: result, Lines: lines, NextActions: []output.NextAction{{Label: "Check readiness", Argv: []string{"agentctl", "doctor"}, Mutates: false, SideEffectClass: output.ReadOnly, Preconditions: []string{}}}})
	return 0
}
